@@ -72 +71,0 @@ static int hash_walk_new_entry(struct crypto_hash_walk *walk)
-	walk->pg = sg_page(sg);
@@ -73,0 +73,2 @@ static int hash_walk_new_entry(struct crypto_hash_walk *walk)
+	walk->pg = sg_page(walk->sg) + (walk->offset >> PAGE_SHIFT);
+	walk->offset = offset_in_page(walk->offset);

