+	bma->got.br_blockcount = bma->length;
 	bma->got.br_state = XFS_EXT_NORM;

 	/*
@@ -4736,8 +4720,9 @@ xfs_bmapi_allocate(
 	 */
 	xfs_bmbt_get_all(xfs_iext_get_ext(ifp, *lastx), &bma->got);

-	ASSERT(bma->got.br_startoff <= aoff);
